FUNCTION_BLOCK FB_Puerta
VAR_INPUT
    puertaAbierta : BOOL; // Entrada que indica si la puerta está abierta
    reset : BOOL; // Entrada para resetear el contador de aperturas
END_VAR

VAR_OUTPUT
    aviso : BOOL; // Salida que indica si se han acumulado 5 o más aperturas
    nAperturas : INT; // Salida que muestra el número de aperturas
END_VAR

VAR
    puertaAbiertaAnterior : BOOL; // Variable para almacenar el estado anterior de puertaAbierta
END_VAR

// Inicialización de variables
IF NOT puertaAbiertaAnterior THEN
    puertaAbiertaAnterior := puertaAbierta;
END_IF

// Lógica de reset
IF reset THEN
    nAperturas := 0;
    aviso := FALSE;
END_IF

// Contador de aperturas
IF puertaAbierta AND NOT puertaAbiertaAnterior THEN
    nAperturas := nAperturas + 1;
END_IF

// Actualización del estado anterior de puertaAbierta
puertaAbiertaAnterior := puertaAbierta;

// Lógica de aviso
IF nAperturas >= 5 THEN
    aviso := TRUE;
ELSE
    aviso := FALSE;
END_IF
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Puerta
VAR_INPUT
    puertaAbierta : BOOL; // Entrada que indica si la puerta está abierta
    reset : BOOL; // Entrada para resetear el contador de aperturas
END_VAR

VAR_OUTPUT
    aviso : BOOL; // Salida que indica si se han acumulado 5 o más aperturas
    nAperturas : INT; // Salida que muestra el número de aperturas
END_VAR

VAR
    puertaAbiertaAnterior : BOOL; // Variable para almacenar el estado anterior de puertaAbierta
END_VAR

// Inicialización de variables
IF reset THEN
    nAperturas := 0;
    aviso := FALSE;
    puertaAbiertaAnterior := FALSE;
END_IF

// Detectar transición de FALSE a TRUE en puertaAbierta
IF NOT puertaAbiertaAnterior AND puertaAbierta THEN
    nAperturas := nAperturas + 1;
END_IF

// Actualizar el estado anterior de puertaAbierta
puertaAbiertaAnterior := puertaAbierta;

// Activar la salida de aviso si se han acumulado 5 o más aperturas
IF nAperturas >= 5 THEN
    aviso := TRUE;
ELSE
    aviso := FALSE;
END_IF
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Puerta
VAR_INPUT
    puertaAbierta : BOOL; // Señal de estado de la puerta (TRUE = abierta)
    reset : BOOL;         // Señal para reiniciar el contador y apagar el aviso
END_VAR

VAR_OUTPUT
    aviso : BOOL;         // Indicador de 5 o más aperturas
    nAperturas : INT;     // Registro del número de aperturas
END_VAR

VAR
    flancoApertura : R_TRIG; // Instancia para detectar el flanco de subida
END_VAR

// Detección de la transición de FALSE a TRUE en la entrada puertaAbierta
flancoApertura(CLK := puertaAbierta);

// Lógica de reinicio y conteo de aperturas
IF reset THEN
    nAperturas := 0;
ELSIF flancoApertura.Q THEN
    nAperturas := nAperturas + 1;
END_IF;

// Evaluación de la salida de aviso (se desactiva automáticamente al resetear)
aviso := (nAperturas >= 5);

END_FUNCTION_BLOCK
